<template>
  <div class="page-stack">
    <div class="page-heading"><div><div class="eyebrow">{{ purchase ? 'PROCUREMENT' : packages ? 'PACKAGING STOCK' : 'LOCAL INVENTORY' }}</div><h1>{{ title }}</h1><p>{{ purchase ? '创建采购单、确认到货并按批次办理入库' : '库存台账及每一次库存变化的业务流水' }}</p></div>
      <el-button v-if="purchase" type="primary" @click="openCreate">新建采购单</el-button>
      <el-button v-else type="primary" @click="operationVisible=true">库存业务操作</el-button>
    </div>
    <el-card shadow="never">
      <div class="toolbar">
        <el-input v-model="q" clearable :placeholder="purchase ? '采购单号 / 快递单号 / 订单编号 / 供应商（可扫描）' : packages ? '包材编码 / 名称' : '内部 SKU / 商品名称'" style="max-width:380px" @keyup.enter="load" />
        <el-button type="primary" @click="load">查询</el-button>
        <el-radio-group v-if="!purchase" v-model="tab" @change="load"><el-radio-button label="stock">库存</el-radio-button><el-radio-button label="flow">库存流水</el-radio-button></el-radio-group>
      </div>
      <template v-if="purchase">
        <el-table :data="items" v-loading="loading" stripe>
          <el-table-column prop="poNo" label="采购单号" min-width="170"/><el-table-column prop="trackingNo" label="快递单号" min-width="150"><template #default="{row}">{{ row.trackingNo||'—' }}</template></el-table-column><el-table-column prop="orderNo" label="订单编号" min-width="150"><template #default="{row}">{{ row.orderNo||'—' }}</template></el-table-column><el-table-column prop="supplierName" label="供应商"/><el-table-column prop="status" label="采购状态" width="130"><template #default="{row}">{{ purchaseStatusText(row.status) }}</template></el-table-column><el-table-column label="异常标记" width="120"><template #default="{row}"><el-tag v-if="row.isAbnormal" type="danger">异常待处理</el-tag><el-tag v-else-if="row.abnormalHandledAt" type="success">已处理</el-tag><span v-else>—</span></template></el-table-column><el-table-column prop="expectedArrivalDate" label="预计到货" width="130"/><el-table-column prop="totalAmount" label="采购金额（人民币）"/><el-table-column label="操作" min-width="350" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openDetail(row.id)">明细</el-button><el-button link type="primary" :disabled="!['DRAFT','CONFIRMED','PARTIALLY_RECEIVED'].includes(row.status)" @click="openConfirm(row.id)">确认到货</el-button><el-button link type="success" :disabled="!['CONFIRMED','PARTIALLY_RECEIVED'].includes(row.status)" @click="openReceipt(row.id)">分批入库</el-button><el-button v-if="!row.isAbnormal" link type="danger" @click="openAbnormal(row)">标记异常</el-button><el-button v-else link type="warning" @click="openResolve(row)">处理异常</el-button></template></el-table-column>
        </el-table>
      </template>
      <template v-else-if="tab==='stock'">
        <el-table :data="items" v-loading="loading" stripe>
          <el-table-column prop="code" :label="packages?'包材编码':'内部 SKU'" min-width="160"/><el-table-column prop="name" :label="packages?'包材名称':'商品名称'" min-width="180"/><el-table-column v-if="packages" prop="category" label="包材分类"><template #default="{row}">{{ packageCategoryText(row.category) }}</template></el-table-column><el-table-column v-if="packages" prop="unit" label="单位" width="90"/><el-table-column prop="availableQty" label="可用库存" width="125"/><el-table-column v-if="!packages" prop="lockedQty" label="锁定库存" width="125"/><el-table-column v-if="!packages" prop="pendingInboundQty" label="待入库" width="125"/><el-table-column v-if="!packages" prop="pendingOutboundQty" label="待出库" width="125"/><el-table-column v-if="packages" prop="safetyStock" label="安全库存" width="125"/>
        </el-table>
      </template>
      <template v-else>
        <el-table :data="items" v-loading="loading" stripe>
          <el-table-column prop="createdAt" label="发生时间" min-width="170"/><el-table-column prop="code" :label="packages?'包材编码':'内部 SKU'"/><el-table-column prop="name" label="名称" min-width="150"/><el-table-column v-if="packages" prop="category" label="包材分类"><template #default="{row}">{{ packageCategoryText(row.category) }}</template></el-table-column><el-table-column prop="flowType" label="流水类型"><template #default="{row}">{{ flowTypeText(row.flowType) }}</template></el-table-column><el-table-column prop="quantityDelta" label="数量变化"/><el-table-column prop="availableBefore" label="变更前"/><el-table-column prop="availableAfter" label="变更后"/><el-table-column v-if="!packages" prop="pendingInboundAfter" label="待入库（变更后）"/><el-table-column prop="referenceType" label="来源"><template #default="{row}">{{ flowSourceText(row.referenceType,row.referenceId) }}</template></el-table-column><el-table-column prop="reason" label="原因" min-width="160"/>
        </el-table>
      </template>
      <el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" layout="total, prev, pager, next" @current-change="load"/>
    </el-card>

    <el-dialog v-model="createVisible" title="新建采购单" width="760px"><el-form label-position="top"><div class="master-form"><el-form-item label="供应商"><el-select v-model="createForm.supplierId" filterable placeholder="选择供应商"><el-option v-for="s in lookups.suppliers" :key="s.id" :label="s.supplierName" :value="s.id"/></el-select></el-form-item><el-form-item label="预计到货日期"><el-date-picker v-model="createForm.expectedArrivalDate" value-format="YYYY-MM-DD" type="date" placeholder="选择日期"/></el-form-item><el-form-item label="快递单号（选填）"><el-input v-model="createForm.trackingNo" placeholder="可后续补充，入库时支持扫描检索"/></el-form-item><el-form-item label="订单编号（选填）"><el-input v-model="createForm.orderNo" placeholder="供应商订单编号或业务订单编号"/></el-form-item><el-form-item class="span-two" label="备注"><el-input v-model="createForm.note"/></el-form-item></div></el-form><el-table :data="createForm.items" border><el-table-column label="SKU" min-width="240"><template #default="{row}"><el-select v-model="row.skuId" filterable placeholder="搜索 SKU"><el-option v-for="s in lookups.skus" :key="s.id" :label="`${s.internalSku} · ${s.productName}`" :value="s.id"/></el-select></template></el-table-column><el-table-column label="采购数量"><template #default="{row}"><el-input-number v-model="row.quantity" :min="0.0001" :precision="4"/></template></el-table-column><el-table-column label="单价（人民币）"><template #default="{row}"><el-input-number v-model="row.unitPrice" :min="0" :precision="4"/></template></el-table-column><el-table-column label="操作" width="80"><template #default="{ $index }"><el-button link type="danger" @click="createForm.items.splice($index,1)">删除</el-button></template></el-table-column></el-table><el-button class="add-line" @click="addLine">添加 SKU</el-button><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="createPurchase">创建</el-button></template></el-dialog>

    <el-dialog v-model="detailVisible" :title="`采购单 ${detail?.poNo||''}`" width="820px"><div class="dialog-meta">{{ detail?.supplierName }} · 状态：{{ purchaseStatusText(detail?.status) }} · 预计到货：{{ detail?.expectedArrivalDate||'未设置' }}<br/>快递单号：{{ detail?.trackingNo||'未填写' }} · 订单编号：{{ detail?.orderNo||'未填写' }}<br/><span v-if="detail?.abnormalReason">异常说明：{{ detail.abnormalReason }} {{ detail.abnormalHandlingNote ? `· 处理结果：${detail.abnormalHandlingNote}` : '' }}</span></div><el-table :data="detail?.items||[]"><el-table-column prop="internalSku" label="内部 SKU"/><el-table-column prop="productName" label="商品"/><el-table-column prop="orderedQty" label="采购数量"/><el-table-column prop="confirmedQty" label="已确认"/><el-table-column prop="receivedQty" label="已入库"/><el-table-column prop="unitPrice" label="单价（人民币）"/><el-table-column prop="totalAmount" label="金额（人民币）"/></el-table><template #footer><el-button @click="detailVisible=false">关闭</el-button></template></el-dialog>

    <el-dialog v-model="abnormalVisible" :title="resolvingAbnormal?'处理采购异常':'标记采购异常'" width="520px"><el-alert v-if="resolvingAbnormal" :title="`异常原因：${activePurchase?.abnormalReason||'未填写'}`" type="warning" :closable="false"/><el-form label-position="top"><el-form-item :label="resolvingAbnormal?'处理结果':'异常原因'" required><el-input v-model="abnormalNote" type="textarea" :rows="4" :placeholder="resolvingAbnormal?'填写处理措施和结果':'描述该采购单的异常情况'"/></el-form-item></el-form><template #footer><el-button @click="abnormalVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveAbnormal">{{ resolvingAbnormal?'完成处理':'确认标记' }}</el-button></template></el-dialog>

    <el-dialog v-model="confirmVisible" title="确认到货" width="800px"><el-alert title="确认数量会记入商品库存的待入库数量，不会增加可用库存；实际收货请使用分批入库。" type="info" :closable="false"/><el-table :data="detail?.items||[]"><el-table-column prop="internalSku" label="内部 SKU"/><el-table-column prop="orderedQty" label="采购数量"/><el-table-column label="确认到货数量"><template #default="{row}"><el-input-number v-model="row.confirmInput" :min="0" :precision="4"/></template></el-table-column><el-table-column label="超量确认原因"><template #default="{row}"><el-input v-model="row.overReceiptReason" placeholder="超过采购数量时必填"/></template></el-table-column></el-table><template #footer><el-button @click="confirmVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="confirmPurchase">确认</el-button></template></el-dialog>

    <el-dialog v-model="receiptVisible" title="采购分批入库" width="790px"><el-table :data="detail?.items||[]"><el-table-column prop="internalSku" label="内部 SKU"/><el-table-column prop="orderedQty" label="采购数量"/><el-table-column prop="receivedQty" label="已入库"/><el-table-column label="本次入库"><template #default="{row}"><el-input-number v-model="row.receiptInput" :min="0" :precision="4"/></template></el-table-column><el-table-column label="超收原因"><template #default="{row}"><el-input v-model="row.overReceiptReason" placeholder="超出采购数量时必填"/></template></el-table-column></el-table><template #footer><el-button @click="receiptVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="receivePurchase">提交入库</el-button></template></el-dialog>

    <el-dialog v-model="operationVisible" :title="packages?'包材库存操作':'商品库存操作'" width="560px"><el-form label-position="top"><el-form-item label="操作类型"><el-select v-model="opForm.operation"><el-option label="入库" value="INBOUND"/><el-option label="出库" value="OUTBOUND"/><el-option label="盘点（填写实盘数）" value="COUNT"/><el-option label="调整（正数增加，负数减少）" value="ADJUST"/></el-select></el-form-item><el-form-item :label="packages?'包材':'内部 SKU'"><el-select v-if="packages" v-model="opForm.materialId" filterable><el-option v-for="x in lookups.materials" :key="x.id" :label="`${x.materialCode} · ${x.materialName}`" :value="x.id"/></el-select><el-select v-else v-model="opForm.skuId" filterable><el-option v-for="x in lookups.skus" :key="x.id" :label="`${x.internalSku} · ${x.productName}`" :value="x.id"/></el-select></el-form-item><el-form-item :label="opForm.operation==='COUNT'?'实盘数量':opForm.operation==='ADJUST'?'调整数量（可正可负）':'数量'"><el-input-number v-model="opForm.quantity" :precision="4" :step="1"/></el-form-item><el-form-item label="原因" :required="['COUNT','ADJUST'].includes(opForm.operation)"><el-input v-model="opForm.reason" type="textarea" placeholder="盘点、调整必须填写原因；包材出库不足时会自动生成异常"/></el-form-item></el-form><template #footer><el-button @click="operationVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitOperation">提交</el-button></template></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { api } from '../api'

const props=defineProps<{section:'purchases'|'inventory'|'packages'}>()
const purchase=computed(()=>props.section==='purchases'),packages=computed(()=>props.section==='packages')
const title=computed(()=>purchase.value?'采购管理':packages.value?'包材库存':'本地仓库存')
const q=ref(''),tab=ref('stock'),items=ref<any[]>([]),page=ref(1),pageSize=ref(50),total=ref(0),loading=ref(false),saving=ref(false)
const createVisible=ref(false),detailVisible=ref(false),confirmVisible=ref(false),receiptVisible=ref(false),operationVisible=ref(false),detail=ref<any>()
const lookups=reactive<any>({suppliers:[],skus:[],materials:[]})
const createForm=reactive<any>({supplierId:null,expectedArrivalDate:'',trackingNo:'',orderNo:'',note:'',items:[] as any[]})
const opForm=reactive<any>({operation:'INBOUND',skuId:null,materialId:null,quantity:1,reason:''})
const abnormalVisible=ref(false),resolvingAbnormal=ref(false),activePurchase=ref<any>(),abnormalNote=ref('')
const purchaseStatuses:Record<string,string>={DRAFT:'待确认',CONFIRMED:'已确认待入库',PARTIALLY_RECEIVED:'部分入库',RECEIVED:'已全部入库',CLOSED:'已关闭'}
const flowTypes:Record<string,string>={PURCHASE_CONFIRM:'采购到货确认',PURCHASE_INBOUND:'采购入库',MANUAL_INBOUND:'手工入库',MANUAL_OUTBOUND:'手工出库',STOCK_COUNT:'库存盘点',ADJUSTMENT:'库存调整'}
const flowSources:Record<string,string>={PURCHASE_ORDER:'采购单',PURCHASE_RECEIPT:'采购收货单',MANUAL:'手工操作'}
const packageCategories:Record<string,string>={PRODUCT_PACKAGING:'产品包装',SHIPPING_MATERIAL:'发货打包材料'}
function purchaseStatusText(value?:string){return value?purchaseStatuses[value]||value:'—'}
function flowTypeText(value?:string){return value?flowTypes[value]||value:'—'}
function flowSourceText(value?:string,id?:number){if(!value)return '—';return `${flowSources[value]||value}${id?` #${id}`:''}`}
function packageCategoryText(value?:string){return value?packageCategories[value]||value:'—'}
async function load(){loading.value=true;try{const params=new URLSearchParams({page:String(page.value),pageSize:String(pageSize.value)});if(q.value)params.set('q',q.value);let path='';if(purchase.value)path=`/api/warehouse/purchases?${params}`;else if(tab.value==='flow')path=`/api/warehouse/${packages.value?'packages':'inventory'}/flows?${params}`;else path=`/api/warehouse/${packages.value?'packages':'inventory'}?${params}`;const result=await api<any>(path);items.value=result.items;total.value=result.total}catch(e){ElMessage.error(e instanceof Error?e.message:'加载失败')}finally{loading.value=false}}
async function loadLookups(){Object.assign(lookups,await api<any>('/api/warehouse/lookups'))}
function addLine(){createForm.items.push({skuId:null,quantity:1,unitPrice:0})}
function openCreate(){createForm.supplierId=null;createForm.expectedArrivalDate='';createForm.trackingNo='';createForm.orderNo='';createForm.note='';createForm.items=[];addLine();createVisible.value=true}
async function openDetail(id:number){try{detail.value=await api<any>(`/api/warehouse/purchases/${id}`);detailVisible.value=true}catch(e){ElMessage.error(e instanceof Error?e.message:'读取采购单失败')}}
async function openConfirm(id:number){await openDetail(id);if(!detail.value)return;detail.value.items.forEach((x:any)=>x.confirmInput=x.confirmedQty||x.orderedQty);detailVisible.value=false;confirmVisible.value=true}
async function openReceipt(id:number){await openDetail(id);if(!detail.value)return;detail.value.items.forEach((x:any)=>{x.receiptInput=0;x.overReceiptReason=''});detailVisible.value=false;receiptVisible.value=true}
function openAbnormal(row:any){activePurchase.value=row;abnormalNote.value='';resolvingAbnormal.value=false;abnormalVisible.value=true}
function openResolve(row:any){activePurchase.value=row;abnormalNote.value='';resolvingAbnormal.value=true;abnormalVisible.value=true}
async function saveAbnormal(){const id=activePurchase.value?.id;if(!id||!abnormalNote.value.trim()){ElMessage.warning(resolvingAbnormal.value?'请填写异常处理结果':'请填写异常原因');return}saving.value=true;try{await api(`/api/warehouse/purchases/${id}/abnormal${resolvingAbnormal.value?'/resolve':''}`,{method:'POST',body:JSON.stringify(resolvingAbnormal.value?{handlingNote:abnormalNote.value}:{reason:abnormalNote.value})});ElMessage.success(resolvingAbnormal.value?'采购异常已处理':'已标记采购单异常');abnormalVisible.value=false;await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'异常操作失败')}finally{saving.value=false}}
async function createPurchase(){saving.value=true;try{const r=await api<any>('/api/warehouse/purchases',{method:'POST',body:JSON.stringify(createForm)});ElMessage.success(`采购单 ${r.poNo} 已创建`);createVisible.value=false;await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'创建失败')}finally{saving.value=false}}
async function confirmPurchase(){saving.value=true;try{await api(`/api/warehouse/purchases/${detail.value.id}/confirm`,{method:'POST',body:JSON.stringify({items:detail.value.items.map((x:any)=>({itemId:x.id,confirmedQty:x.confirmInput,overReceiptReason:x.overReceiptReason}))})});ElMessage.success('到货数量已确认，已更新待入库库存');confirmVisible.value=false;await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'确认失败')}finally{saving.value=false}}
async function receivePurchase(){const lines=detail.value.items.filter((x:any)=>Number(x.receiptInput)>0);if(!lines.length){ElMessage.warning('请输入本次入库数量');return}saving.value=true;try{const result=await api<any>(`/api/warehouse/purchases/${detail.value.id}/receipts`,{method:'POST',body:JSON.stringify({items:lines.map((x:any)=>({itemId:x.id,quantity:x.receiptInput,overReceiptReason:x.overReceiptReason}))})});ElMessage.success(`入库完成，流水单号 ${result.receiptNo}`);receiptVisible.value=false;await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'入库失败')}finally{saving.value=false}}
async function submitOperation(){const body={operation:opForm.operation,quantity:opForm.quantity,reason:opForm.reason,...(packages.value?{materialId:opForm.materialId}:{skuId:opForm.skuId})};saving.value=true;try{const r=await api<any>(`/api/warehouse/${packages.value?'packages':'inventory'}/operations`,{method:'POST',body:JSON.stringify(body)});if(r.warning)ElMessage.warning(r.warning);else ElMessage.success('库存流水已生成');operationVisible.value=false;await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'库存操作失败')}finally{saving.value=false}}
onMounted(async()=>{await loadLookups();await load()})
</script>
